        AsmaulHusna(88, "الْغَنِيُّ", "Al-Ghaniyy", "Maha Kaya", "The Rich One", "Cukup dan berkecukupan; tidak tergantung pada dunia untuk bahagia.", "Be content and self-sufficient; do not depend on worldly things for happiness."),
        AsmaulHusna(89, "الْمُغْنِي", "Al-Mughni", "Maha Memberi Kekayaan", "The Enricher", "Berikan manfaat agar orang lain bertambah; membantu adalah cara memperkaya.", "Provide benefit so others prosper; helping enriches lives."),
        AsmaulHusna(90, "الْمَانِعُ", "Al-Mani'", "Maha Mencegah", "The Withholder", "Lindungi apa yang penting; pencegahan sering lebih bijak daripada perbaikan.", "Protect what matters; prevention is often wiser than repair."),
        AsmaulHusna(91, "الضَّارُّ", "Ad-Darr", "Maha Memberi Kemudharatan", "The Distresser", "Terima ujian sebagai pelajaran; hadapi kesulitan dengan sabar dan bijak.", "Accept trials as lessons; face hardship with patience and wisdom."),
        AsmaulHusna(92, "النَّافِعُ", "An-Nafi'", "Maha Memberi Manfaat", "The Benefactor", "Berfokus pada manfaat bagi banyak orang; kontribusi kecil bernilai besar.", "Focus on benefit for many; small contributions hold great value."),
        AsmaulHusna(93, "النُّورُ", "An-Nur", "Maha Cahaya", "The Light", "Jadilah cahaya yang memberi petunjuk; sebarkan kebaikan yang menerangi.", "Be a guiding light; spread goodness that enlightens."),
        AsmaulHusna(94, "الْهَادِي", "Al-Hadi", "Maha Memberi Petunjuk", "The Guide", "Carilah petunjuk dalam tindakan; arah yang jelas memudahkan langkah.", "Seek guidance in action; clear direction eases the path."),
        AsmaulHusna(95, "الْبَدِيعُ", "Al-Badi'", "Maha Pencipta Keindahan", "The Incomparable", "Ciptakan keindahan dalam kebaikan; inovasi yang baik menginspirasi banyak orang.", "Create beauty through goodness; good innovation inspires many."),
        AsmaulHusna(96, "الْبَاقِي", "Al-Baqi", "Maha Kekal", "The Everlasting", "Berbuat yang berkekalan; tinggalkan jejak kebaikan yang abadi.", "Do what endures; leave a legacy of lasting good."),
        AsmaulHusna(97, "الْوَارِثُ", "Al-Warith", "Maha Pewaris", "The Inheritor", "Persiapkan warisan yang bermanfaat; amalan baik mewarisi kebaikan.", "Prepare a beneficial legacy; good deeds bequeath goodness."),
        AsmaulHusna(98, "الرَّشِيدُ", "Ar-Rasyid", "Maha Pandai", "The Righteous Guide", "Berjalanlah di jalan yang benar; petunjuk membimbing pada keputusan bijak.", "Walk the right path; guidance leads to wise decisions."),
        AsmaulHusna(99, "الصَّبُورُ", "As-Sabur", "Maha Penyabar", "The Patient One", "Latih kesabaran; ketekunan mendatangkan hasil dan ketenteraman.", "Practice patience; perseverance brings results and peace.")
    )
}
